from collections import deque

def find_connected_regions(arr, target_val=0):
    """Find 4-connected components of target_val"""
    rows, cols = len(arr), len(arr[0])
    visited = set()
    regions = []

    for r in range(rows):
        for c in range(cols):
            if arr[r][c] == target_val and (r,c) not in visited:
                region = []
                queue = deque([(r,c)])
                visited.add((r,c))
                while queue:
                    cur_r, cur_c = queue.popleft()
                    region.append((cur_r, cur_c))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cur_r + dr, cur_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if arr[nr][nc] == target_val and (nr,nc) not in visited:
                                visited.add((nr,nc))
                                queue.append((nr,nc))
                regions.append((len(region), region))

    return regions

def flood_fill_from_8_to_0s(arr):
    """Fill all 0s connected to any 8 with 8"""
    result = [row[:] for row in arr]

